WITH unpacked AS (SELECT id, plan, effective_from, currency, tier_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT id, plan, effective_from, entry_price, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY avg_tier_price, id) AS event_seq, AVG(lowest_price) OVER w_hist AS lowest_price_avg_6, NTILE(3) OVER (PARTITION BY plan ORDER BY lowest_price DESC, id) AS lowest_price_bucket, RANK() OVER (PARTITION BY currency ORDER BY avg_tier_price NULLS FIRST) AS avg_tier_price_rank, SUM(entry_price) OVER (ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_entry_price FROM unpacked WHERE lowest_price <= 18 WINDOW w_hist AS (PARTITION BY currency, plan ORDER BY effective_from, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
